            - CLAUDE_CODE_SKIP_BEDROCK_AUTH=${CLAUDE_CODE_SKIP_BEDROCK_AUTH}
            - BEDROCK_REGION=${BEDROCK_REGION}
            - BEDROCK_ACCESS_KEY_ID=${BEDROCK_ACCESS_KEY_ID}
            - BEDROCK_SECRET_ACCESS_KEY=${BEDROCK_SECRET_ACCESS_KEY}
            - BEDROCK_SESSION_TOKEN=${BEDROCK_SESSION_TOKEN}
            - BEDROCK_USE_DEFAULT_CREDENTIALS=${BEDROCK_USE_DEFAULT_CREDENTIALS}
            - BEDROCK_MODEL_NAME=${BEDROCK_MODEL_NAME}
            - BEDROCK_INFERENCE_PROFILE_PREFIX=${BEDROCK_INFERENCE_PROFILE_PREFIX}
            - BEDROCK_EMBEDDING_MODEL=${BEDROCK_EMBEDDING_MODEL}
            - BEDROCK_TEMPERATURE=${BEDROCK_TEMPERATURE}
            - BEDROCK_AVAILABLE_MODELS=${BEDROCK_AVAILABLE_MODELS}
            - GOOGLE_DRIVE_API_KEY=${GOOGLE_DRIVE_API_KEY}
            - SLACK_SIGNING_SECRET=${SLACK_SIGNING_SECRET}
            - SLACK_CLIENT_ID=${SLACK_CLIENT_ID}
            - SLACK_CLIENT_SECRET=${SLACK_CLIENT_SECRET}
            - SLACK_STATE_SECRET=${SLACK_STATE_SECRET}
            - GITHUB_PRIVATE_KEY=${GITHUB_PRIVATE_KEY}
            - GITHUB_APP_ID=${GITHUB_APP_ID}
            - GITHUB_CLIENT_ID=${GITHUB_CLIENT_ID}
            - GITHUB_CLIENT_SECRET=${GITHUB_CLIENT_SECRET}
            - GITHUB_APP_NAME=${GITHUB_APP_NAME}
            - GITHUB_REDIRECT_DOMAIN=${GITHUB_REDIRECT_DOMAIN}
            - S3_ENDPOINT=${S3_ENDPOINT:-http://minio:9000}
            - S3_REGION=${S3_REGION:-us-east-1}
            - S3_BUCKET=${S3_BUCKET:-default}
            - S3_ACCESS_KEY=${S3_ACCESS_KEY:-minioadmin}
            - S3_SECRET_KEY=${S3_SECRET_KEY:-minioadmin}
            - S3_FORCE_PATH_STYLE=${S3_FORCE_PATH_STYLE:-true}
            - S3_EXPIRATION_TIME=${S3_EXPIRATION_TIME}
            - RESULTS_S3_ENDPOINT=${RESULTS_S3_ENDPOINT}
            - RESULTS_S3_FORCE_PATH_STYLE=${RESULTS_S3_FORCE_PATH_STYLE}
            - RESULTS_S3_REGION=${RESULTS_S3_REGION:-${RESULTS_CACHE_S3_REGION}}
            - RESULTS_S3_BUCKET=${RESULTS_S3_BUCKET:-${RESULTS_CACHE_S3_BUCKET}}
            - RESULTS_S3_SECRET_KEY=${RESULTS_S3_SECRET_KEY:-${RESULTS_CACHE_S3_SECRET_KEY}}
            - RESULTS_S3_ACCESS_KEY=${RESULTS_S3_ACCESS_KEY:-${RESULTS_CACHE_S3_ACCESS_KEY}}
            - TURBO_TOKEN=${TURBO_TOKEN}
            - TURBO_TEAM=${TURBO_TEAM}
