      - socioboard-mongo
    environment:
      BASE_DOMAIN: ${BASE_DOMAIN}
      HTTP_PORT: ${HTTP_PORT}
      HTTPS_PORT: ${HTTPS_PORT}
      AUTH_SECRET: ${AUTH_SECRET}
      AUTH_TOKEN_SECRET: ${AUTH_TOKEN_SECRET}
