volumes:
  scb-mongo: {}
  scb-mysql: {}
networks:
  scb-net:
    driver: bridge

services:
  app:
    build:
      context: .
      dockerfile: Dockerfile
      target: development
    tty: true
    stdin_open: true
    environment:
      MODE: DEV
      BINDING: "0.0.0.0"
      POSTGRES_DATABASE: ${POSTGRES_DB:-teammapper-backend-dev}
      POSTGRES_HOST: ${POSTGRES_HOST:-postgres}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-teammapper-password}
      POSTGRES_PORT: ${POSTGRES_PORT:-5432}
      POSTGRES_USER: ${POSTGRES_USER:-teammapper-user}
      POSTGRES_SSL: ${POSTGRES_SSL:-false}
      POSTGRES_QUERY_TIMEOUT: ${POSTGRES_QUERY_TIMEOUT:-100000}
      POSTGRES_STATEMENT_TIMEOUT: ${POSTGRES_STATEMENT_TIMEOUT:-100000}
      POSTGRES_TEST_DATABASE: ${DOCKER_COMPOSE_APP_ENV_POSTGRES_TEST_DATABASE:-teammapper-backend-test}
      POSTGRES_TEST_HOST: ${DOCKER_COMPOSE_APP_ENV_POSTGRES_HOST:-postgres}
      POSTGRES_TEST_PASSWORD: ${DOCKER_COMPOSE_APP_ENV_POSTGRES_PASSWORD:-teammapper-password}
      POSTGRES_TEST_PORT: ${DOCKER_COMPOSE_APP_ENV_POSTGRES_PORT:-5432}
      POSTGRES_TEST_USER: ${DOCKER_COMPOSE_APP_ENV_POSTGRES_USER:-teammapper-user}
      DELETE_AFTER_DAYS: ${DELETE_AFTER_DAYS:-30}
      AI_LLM_PROVIDER: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_PROVIDER}
      AI_LLM_URL: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_URL}
      AI_LLM_TOKEN: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_TOKEN}
      AI_LLM_MODEL: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_MODEL}
      AI_LLM_RPM: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_RPM}
      AI_LLM_TPM: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_TPM}
      AI_LLM_TPD: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_TPD}
      AI_LLM_MAX_OUTPUT_TOKENS: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_MAX_OUTPUT_TOKENS}
      AI_LLM_TIMEOUT_MS: ${DOCKER_COMPOSE_APP_ENV_AI_LLM_API_TIMEOUT_MS}
      JWT_SECRET: ${JWT_SECRET}
      LOG_LEVEL: ${LOG_LEVEL:-debug}

      TESTING_PLAYWRIGHT_WS_ENDPOINT: "ws://playwright:9323"
      TESTING_PLAYWRIGHT_BASE_URL: "http://app:4200"
      PLAYWRIGHT_MCP_CDP_ENDPOINT: "http://chrome:9222"
    ports:
      - "${APP_FRONTEND_PORT:-4200}:4200"
      - "${APP_BACKEND_PORT:-3000}:3000"
      # karma server
      - 9876:9876
    volumes:
      - .:/home/node/app
      - app_backend_node_modules:/home/node/app/teammapper-backend/node_modules
      - app_frontend_node_modules:/home/node/app/teammapper-frontend/node_modules
    depends_on:
      - postgres

  postgres:
    image: postgres:15-alpine
    environment:
      PGDATA: /var/lib/postgresql/data/pgdata
      POSTGRES_DB: ${POSTGRES_DB:-teammapper-backend-dev}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-teammapper-password}
      POSTGRES_USER: ${POSTGRES_USER:-teammapper-user}
    # Exposing the port is not needed unless you want to access this database instance from the host.
    # Be careful when other postgres docker container are running on the same port
    ports:
      - "${POSTGRES_PORT:-5432}:5432"
    volumes:
      - postgres_data:/var/lib/postgresql/data/pgdata

  playwright:
    image: mcr.microsoft.com/playwright:v1.63.0-noble
    container_name: playwright
    depends_on:
      - app
    expose:
      - "9323"
    command: ["npx", "playwright", "run-server", "--port=9323", "--host=0.0.0.0"]

  chrome:
    image: chromedp/headless-shell:latest
    container_name: chrome
    depends_on:
      - app
    expose:
      - "9222"
    # headless-shell listens on 9222 by default with --remote-debugging-address=0.0.0.0

volumes:
  postgres_data:
  app_backend_node_modules:
  app_frontend_node_modules:

services:
    db:
        image: postgres:15-alpine
        restart: unless-stopped
        environment:
            POSTGRES_DB: ${DATABASE_NAME:-trackwatch}
            POSTGRES_USER: ${DATABASE_USER:-trackwatch}
            POSTGRES_PASSWORD: ${DATABASE_PASSWORD:?Database password required}
        volumes:
            - postgres_data:/var/lib/postgresql/data
        healthcheck:
            test:
                [
                    "CMD-SHELL",
                    "pg_isready -U ${DATABASE_USER:-trackwatch} -d ${DATABASE_NAME:-trackwatch}",
                ]
            interval: 10s
            timeout: 5s
            retries: 5
        networks:
            - trackwatch-network

    backend:
        image: ${BACKEND_IMAGE:-ghcr.io/emlopezr/trackwatch-backend:latest}
        build:
            context: ./backend
            dockerfile: Dockerfile
            target: backend
        restart: unless-stopped
        environment: &backend-env
            # Django settings
            SECRET_KEY: ${SECRET_KEY:?Django secret key required}
            ADMIN_KEY: ${ADMIN_KEY:?Admin webhook key required}
            DEBUG: ${DEBUG:-False}
            ALLOWED_HOSTS: ${ALLOWED_HOSTS:-localhost,127.0.0.1,backend}
            CORS_ALLOWED_ORIGINS: ${CORS_ALLOWED_ORIGINS:-http://localhost:5173,http://127.0.0.1:5173,https://trackwatch.emlopezr.com}
            CSRF_TRUSTED_ORIGINS: ${CSRF_TRUSTED_ORIGINS:-http://localhost:5173,http://127.0.0.1:5173,https://trackwatch.emlopezr.com}
            SECURE_SSL_REDIRECT: ${SECURE_SSL_REDIRECT:-False}
            SECURE_HSTS_SECONDS: ${SECURE_HSTS_SECONDS:-0}
            SECURE_HSTS_INCLUDE_SUBDOMAINS: ${SECURE_HSTS_INCLUDE_SUBDOMAINS:-False}
            SECURE_HSTS_PRELOAD: ${SECURE_HSTS_PRELOAD:-False}

            # Database
            DATABASE_NAME: ${DATABASE_NAME:-trackwatch}
            DATABASE_USER: ${DATABASE_USER:-trackwatch}
            DATABASE_PASSWORD: ${DATABASE_PASSWORD:?Database password required}
            DATABASE_HOST: db
            DATABASE_PORT: 5432

            # Spotify
            SPOTIFY_CLIENT_ID: ${SPOTIFY_CLIENT_ID:?Spotify Client ID required}
            SPOTIFY_CLIENT_SECRET: ${SPOTIFY_CLIENT_SECRET:?Spotify Client Secret required}

            # Optional: Email service
            RESEND_API_KEY: ${RESEND_API_KEY:-}
            ADMIN_EMAIL: ${ADMIN_EMAIL:-}
            EMAIL_DOMAIN: ${EMAIL_DOMAIN:-emlopezr.com}
            FRONTEND_BASE_URL: ${FRONTEND_BASE_URL:-https://trackwatch.emlopezr.com}

            # Gunicorn configuration
            GUNICORN_WORKERS: ${GUNICORN_WORKERS:-2}
            GUNICORN_THREADS: ${GUNICORN_THREADS:-4}
            GUNICORN_TIMEOUT: ${GUNICORN_TIMEOUT:-120}
        healthcheck:
            test: ["CMD", "curl", "-f", "http://localhost:8000/ping"]
            interval: 10s
            timeout: 5s
            retries: 10
            start_period: 30s
        depends_on:
            db:
                condition: service_healthy
        networks:
            - trackwatch-network

    scheduler:
        image: ${SCHEDULER_IMAGE:-ghcr.io/emlopezr/trackwatch-scheduler:latest}
        profiles:
            - scheduler
        build:
            context: ./backend
            dockerfile: Dockerfile
            target: scheduler
        restart: unless-stopped
        environment:
            <<: *backend-env
            SCHEDULER_HOURS: ${SCHEDULER_HOURS:-7,14,21}
            SCHEDULER_MINUTE: ${SCHEDULER_MINUTE:-0}
        depends_on:
            backend:
                condition: service_healthy
        networks:
            - trackwatch-network

    frontend:
        image: ${FRONTEND_IMAGE:-ghcr.io/emlopezr/trackwatch-frontend:latest}
        build:
            context: ./frontend
            dockerfile: Dockerfile
        restart: unless-stopped
        environment:
            VITE_HIDE_PUBLIC_LOGIN: ${VITE_HIDE_PUBLIC_LOGIN:-false}
            BACKEND_PROXY_PASS: ${BACKEND_PROXY_PASS:-http://backend:8000}
            BACKEND_PROXY_HOST: ${BACKEND_PROXY_HOST:-backend}
            NGINX_RESOLVER: ${NGINX_RESOLVER:-127.0.0.11}
        ports:
            - "${PORT:-80}:80"
        depends_on:
            - backend
        networks:
            - trackwatch-network

volumes:
    postgres_data:
        name: trackwatch_postgres_data

networks:
    trackwatch-network:
        name: trackwatch-network
        driver: bridge
